package dev.voyage.workbench;
import org.json.*;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;
final class Providers {
 final AgentService agent;Providers(AgentService a){agent=a;}
 static JSONObject http(String url,JSONObject headers,String body)throws Exception{return httpBytes(url,headers,body==null?null:body.getBytes(StandardCharsets.UTF_8));}
 static JSONObject httpBytes(String url,JSONObject headers,byte[] body)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();try{c.setInstanceFollowRedirects(false);c.setConnectTimeout(20000);c.setReadTimeout(120000);c.setRequestMethod(body==null?"GET":"POST");java.util.Iterator<String> keys=headers.keys();while(keys.hasNext()){String key=keys.next();c.setRequestProperty(key,headers.getString(key));}if(body!=null){c.setDoOutput(true);try(OutputStream out=c.getOutputStream()){out.write(body);}}int status=c.getResponseCode();if(status<200||status>=300)throw new Exception("Provider HTTP "+status+". Check the endpoint, key, and model.");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>32*1024*1024)throw new Exception("Provider response exceeds 32 MiB");out.write(buffer,0,n);}return new JSONObject(out.toString("UTF-8"));}}finally{c.disconnect();}}
 void run(JSONObject t)throws Exception{JSONObject route=t.getJSONObject("route");Secrets secrets=new Secrets(agent);String key=secrets.get("provider-"+route.getString("id"));boolean work="work".equals(t.getString("kind"));JSONArray messages=new JSONArray().put(new JSONObject().put("role","user").put("text",new JSONObject().put("request",t.getString("prompt")).put("memory",agent.store.project(agent.projectId).optString("memory")).put("workOrder",t.getJSONObject("workOrder")).put("history",agent.store.project(agent.projectId).getJSONArray("chat")).put("context",agent.store.core.doc("context",t.getString("baseSource"),t.getString("prompt"))).toString()));long end=System.currentTimeMillis()+30*60*1000;StringBuilder reply=new StringBuilder();
 for(int turn=0;turn<80;turn++){if(agent.canceled||System.currentTimeMillis()>end)throw new Exception("Task canceled or timed out");agent.store.setting("agentHeartbeat",Long.toString(System.currentTimeMillis()));JSONObject result;if("claude-code".equals(route.getString("protocol")))result=ClaudeHarness.turn(agent,agent.store.core,route,messages,work,()->agent.canceled);else if("cursor".equals(route.getString("protocol")))result=CursorHarness.turn(agent,agent.store.core,route,messages,work,()->agent.canceled);else{JSONObject request=(JSONObject)agent.store.core.doc("apiRequest",route,key,messages,work);JSONObject response=http(request.getString("url"),request.getJSONObject("headers"),request.getString("body"));result=(JSONObject)agent.store.core.doc("apiResponse",route.getString("protocol"),response);}if(agent.canceled)throw new Exception("Task canceled");messages.put(result);String text=result.optString("text");if(!text.isEmpty()){if(reply.length()>0)reply.append("\n\n");reply.append(text);agent.command(new JSONObject().put("type","taskReply").put("text",reply.toString()));}JSONArray calls=result.optJSONArray("calls");if(calls==null||calls.length()==0){agent.command(new JSONObject().put("type","taskDone").put("text",reply.toString()));return;}if(calls.length()>50)throw new Exception("Too many tool calls");for(int j=0;j<calls.length();j++){JSONObject call=calls.getJSONObject(j);Object output;try{JSONArray allowed=(JSONArray)agent.store.core.doc("toolDefinitions",work);boolean permitted=false;for(int index=0;index<allowed.length();index++)if(allowed.getJSONObject(index).getString("name").equals(call.getString("name")))permitted=true;if(!permitted)throw new Exception("Tool is unavailable for this stage");output=agent.tool(call.getString("name"),new JSONObject(call.getJSONObject("args").toString()));}catch(Exception e){output=new JSONObject().put("error",e.getMessage());}messages.put(new JSONObject().put("role","tool").put("callId",call.getString("id")).put("name",call.getString("name")).put("text",output.toString()));}}
 throw new Exception("Task reached its 80-turn limit. Review partial changes before restarting.");}
}
